/**
 * Cloudflare Workers entry for the OpenNext build of the Next.js app.
 *
 * `fetch` is the generated OpenNext handler. `scheduled` replaces Vercel Cron:
 * each Cron Trigger calls its existing `/api/cron/*` route through the
 * WORKER_SELF_REFERENCE service binding with the CRON_SECRET bearer token.
 */
// Generated by `opennextjs-cloudflare build`; absent before the first build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "../../.open-next/worker.js";
import { serveWithEdgeCache } from "./edge-html-cache";
import { loadCriticalCss, withCriticalCss } from "./critical-css";
import { withHostRobots } from "./robots-host";
import { signedOutRedirect } from "./signed-out-redirect";
import { versionResponse } from "./version-route";
import { runScheduledRoute, type ScheduledController, type ScheduledEnv } from "./cron-routes";

interface WorkerExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
}

interface FetchEnv {
  CF_VERSION_METADATA?: { id: string };
  BUILD_SHA?: string;
  ASSETS?: { fetch(request: Request): Promise<Response> };
}

const worker = {
  async fetch(request: Request, env: FetchEnv, ctx: WorkerExecutionContext) {
    const version = versionResponse(request, env.BUILD_SHA);
    if (version) return withHostRobots(request, version);
    const redirect = signedOutRedirect(request);
    if (redirect) return redirect;
    return withHostRobots(request, await serveWithEdgeCache(
      request,
      env.CF_VERSION_METADATA?.id,
      (caches as unknown as { default: Cache }).default,
      (promise) => ctx.waitUntil(promise),
      (forwarded) => handler.fetch(forwarded, env, ctx),
      async (response) => withCriticalCss(response, await loadCriticalCss(env.ASSETS)),
    ));
  },
  async scheduled(controller: ScheduledController, env: ScheduledEnv, ctx: WorkerExecutionContext) {
    ctx.waitUntil(runScheduledRoute(controller, env));
  },
};

export default worker;
